export function formatPrice(p) {
  if (p === null || p === undefined || p === "") return "-";
  const s = String(p).trim();
  if (s === "") return "-";
  const n = Number(s);
  if (!Number.isFinite(n)) return "-";
  if (n < 0) return "var";

  // Convert to plain decimal string (avoid exponent), via toFixed-like expansion
  let str = s.toLowerCase();
  if (!/^[+]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/.test(str)) {
    str = n.toExponential(); // fallback
  }
  str = str.replace(/^\+/, "");
  let [mant, exp] = str.split("e");
  let e = exp ? parseInt(exp, 10) : 0;
  let [ip, fp = ""] = mant.split(".");
  let digits = ip + fp;
  let pointPos = ip.length + e + 6; // shift by 1e6
  // We want value in dollars with 2 decimals: scale by 100 more
  pointPos += 2;
  if (pointPos < 0) {
    digits = "0".repeat(-pointPos) + digits;
    pointPos = 0;
  }
  if (pointPos > digits.length) digits = digits + "0".repeat(pointPos - digits.length);
  let whole = digits.slice(0, pointPos) || "0";
  const rest = digits.slice(pointPos);
  let cents = BigInt(whole);
  if (rest.length > 0 && rest[0] >= "5") cents += 1n;
  const cs = cents.toString().padStart(3, "0");
  return "$" + cs.slice(0, -2) + "." + cs.slice(-2);
